export const inject = ['slots']
// 这一段是压缩产物形态的局部变量阴影：slots 在这里是数组，不是服务
export function apply(ctx) {
  const slots = [1, 2, 3]
  slots.push(4)
  slots.add(5)
  const el = { addEventListener() {} }
  el.addEventListener('x', () => {})
  ctx.slots.inject('a', () => {})
  ctx.slots.register({ name: 'a' })
}
